import type { Api } from "@jellyfin/sdk";
import type {
  ImageType,
  ItemFields,
  ItemsApiGetItemsRequest,
  ItemsApiGetResumeItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
  TvShowsApiGetNextUpRequest,
  UserLibraryApiGetLatestMediaRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client/models/base-item-dto";
import type { ImageRequestParameters } from "@jellyfin/sdk/lib/models/api/image-request-parameters";
import { ImageUrlsApi } from "@jellyfin/sdk/lib/utils/api/image-urls-api";
import { Effect } from "effect";
import { isArray, isEmptyArray } from "effect/Array";
import { HttpError, MutationError, NoEpisodeFound } from "../../error";
import { AuthService, AuthServiceLayer } from "../auth";

/*
 *
 *
 *
 *  Helpers
 *
 *
 *
 */

function arrayToObjectWithDuplicates<K extends PropertyKey, V>(
  entries: readonly (readonly [K, V])[]
): Record<K, V | V[]> {
  return entries.reduce(
    (acc, [key, value]) => {
      const existing = acc[key];

      if (existing !== undefined) {
        acc[key] = Array.isArray(existing)
          ? [...existing, value]
          : [existing, value];
      } else {
        acc[key] = value;
      }

      return acc;
    },
    {} as Record<K, V | V[]>
  );
}

const getImageByKey = (jf: Api, item: BaseItemDto, keyTag: ImageType) =>
  new ImageUrlsApi(jf.configuration).getItemImageUrl(item, keyTag, {
    quality: 75,
  });

/**
 * Jellyfin-Web–style fallback chain for the best available primary image.
 * Tries, in order:
 *  1. ImageTags.Primary  (own item)
 *  2. SeriesPrimaryImageTag + SeriesId
 *  3. PrimaryImageTag    (some DTOs carry this at top-level with own Id)
 *  4. ParentPrimaryImageTag + ParentPrimaryImageItemId (inferred from ParentId)
 *  5. AlbumPrimaryImageTag + AlbumId
 *  6. BackdropImageTags  (first own backdrop)
 *  7. SeriesThumbImageTag + SeriesId
 *  8. ParentThumbImageTag + ParentThumbItemId
 *  9. ParentBackdropImageTags + ParentBackdropItemId (first parent backdrop)
 * Falls back to the tagless `/Items/{id}/Images/Primary` URL.
 */
const getBestPrimaryImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string => {
  const id = item.Id ?? "";

  // 1. Own primary tag
  if (item.ImageTags?.Primary) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: item.ImageTags.Primary,
    });
  }

  // 2. Series primary
  if (item.SeriesPrimaryImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Primary" as ImageType, {
      ...params,
      tag: item.SeriesPrimaryImageTag,
    });
  }

  // 3. Top-level PrimaryImageTag (rare but present on some DTOs)
  if ((item as Record<string, unknown>).PrimaryImageTag) {
    return api.getItemImageUrlById(id, "Primary" as ImageType, {
      ...params,
      tag: (item as Record<string, unknown>).PrimaryImageTag as string,
    });
  }

  // 4. Parent primary
  const parentPrimaryId =
    (item as Record<string, unknown>).ParentPrimaryImageItemId as
      | string
      | undefined;
  const parentPrimaryTag =
    (item as Record<string, unknown>).ParentPrimaryImageTag as
      | string
      | undefined;
  if (parentPrimaryTag && parentPrimaryId) {
    return api.getItemImageUrlById(parentPrimaryId, "Primary" as ImageType, {
      ...params,
      tag: parentPrimaryTag,
    });
  }

  // 5. Album primary (music items)
  if (item.AlbumPrimaryImageTag && item.AlbumId) {
    return api.getItemImageUrlById(item.AlbumId, "Primary" as ImageType, {
      ...params,
      tag: item.AlbumPrimaryImageTag,
    });
  }

  // 6. Own backdrop (first)
  if (item.BackdropImageTags && item.BackdropImageTags.length > 0) {
    return api.getItemImageUrlById(id, "Backdrop" as ImageType, {
      ...params,
      tag: item.BackdropImageTags[0],
    });
  }

  // 7. Series thumb
  if (item.SeriesThumbImageTag && item.SeriesId) {
    return api.getItemImageUrlById(item.SeriesId, "Thumb" as ImageType, {
      ...params,
      tag: item.SeriesThumbImageTag,
    });
  }

  // 8. Parent thumb
  if (item.ParentThumbImageTag && item.ParentThumbItemId) {
    return api.getItemImageUrlById(
      item.ParentThumbItemId,
      "Thumb" as ImageType,
      { ...params, tag: item.ParentThumbImageTag },
    );
  }

  // 9. Parent backdrop (first)
  if (
    item.ParentBackdropImageTags &&
    item.ParentBackdropImageTags.length > 0 &&
    item.ParentBackdropItemId
  ) {
    return api.getItemImageUrlById(
      item.ParentBackdropItemId,
      "Backdrop" as ImageType,
      { ...params, tag: item.ParentBackdropImageTags[0] },
    );
  }

  // 10. Tagless fallback
  return api.getItemImageUrlById(id);
};

/**
 * Fallback chain for the best available Logo image URL.
 *  1. ImageTags.Logo (own item)
 *  2. ParentLogoImageTag + ParentLogoItemId
 * Returns undefined when no logo metadata is available.
 */
const getBestLogoImageUrl = (
  api: ImageUrlsApi,
  item: BaseItemDto,
  params: ImageRequestParameters = {},
): string | undefined => {
  const id = item.Id ?? "";

  // 1. Own logo tag
  if (item.ImageTags?.Logo) {
    return api.getItemImageUrlById(id, "Logo" as ImageType, {
      ...params,
      tag: item.ImageTags.Logo,
    });
  }

  // 2. Parent logo
  if (item.ParentLogoImageTag && item.ParentLogoItemId) {
    return api.getItemImageUrlById(item.ParentLogoItemId, "Logo" as ImageType, {
      ...params,
      tag: item.ParentLogoImageTag,
    });
  }

  return;
};

const getImagesFromTags = (
  tags: BaseItemDto["ImageTags"],
  jf: Api,
  item: BaseItemDto
) => {
  if (!tags) {
    return {};
  }
  const images = Object.entries(tags).map(
    ([k, _v]) => [k, getImageByKey(jf, item, k as ImageType)] as const
  );

  return arrayToObjectWithDuplicates(images);
};

export type WithImage<T> = T extends Array<infer U>
  ? Array<U & { Image: string; Images: ReturnType<typeof getImagesFromTags> }>
  : T extends undefined
    ? undefined
    : T & { Image: string; Images: ReturnType<typeof getImagesFromTags> };

export const getImages =
  (jf: Api) =>
  <T extends BaseItemDto | BaseItemDto[] | undefined>(
    items: T
  ): Effect.Effect<WithImage<T>, never, never> => {
    if (!items) {
      return Effect.succeed(undefined as WithImage<T>);
    }

    return Effect.sync(() => {
      if (isArray(items)) {
        return items.map((item) => {
          const imageTags = getImagesFromTags(
            item.ImageTags,
            // jf.basePath,
            jf,
            // item.Id as string
            item
          );

          return {
            ...item,
            Image: getBestPrimaryImageUrl(
              new ImageUrlsApi(jf.configuration),
              item,
            ),
            Images: Object.assign(imageTags, {
              Backdrop: new ImageUrlsApi(
                jf.configuration
              ).getItemBackdropImageUrls(item),
              ...(!imageTags.Logo && {
                Logo: getBestLogoImageUrl(
                  new ImageUrlsApi(jf.configuration),
                  item,
                ),
              }),
            }),
          };
        }) as unknown as WithImage<T>;
      }

      const imageTags = getImagesFromTags(
        items.ImageTags,
        jf,
        // jf.basePath,
        // items.Id as string
        items
      );

      return {
        ...items,
        Image: getBestPrimaryImageUrl(
          new ImageUrlsApi(jf.configuration),
          items,
          { quality: 40 },
        ),
        Images: Object.assign(imageTags, {
          Backdrop: new ImageUrlsApi(jf.configuration).getItemBackdropImageUrls(
            items
          ),
          ...(!imageTags.Logo && {
            Logo: getBestLogoImageUrl(
              new ImageUrlsApi(jf.configuration),
              items,
            ),
          }),
        }),
      } as unknown as WithImage<T>;
    });
  };

const SUPPORTED_COLLECTION_TYPES = ["movies", "tvshows"] as const;

// Helper function to filter supported libraries
const filterSupportedLibraries = (items?: BaseItemDto[]) =>
  Effect.succeed(
    items?.filter(
      (item) =>
        item.CollectionType &&
        // biome-ignore lint/suspicious/noExplicitAny: filtering
        SUPPORTED_COLLECTION_TYPES.includes(item.CollectionType as any)
    ) ?? []
  );

/*
 *
 *
 *
 *  Jellyfin Service
 *
 *
 *
 */

export class JellyfinService extends Effect.Service<JellyfinService>()(
  "JellyfinService",
  {
    dependencies: [AuthServiceLayer],
    effect: Effect.gen(function* () {
      const auth = yield* AuthService;

      /*
       *
       *
       *  Libraries Methods
       *
       *
       */

      // Helper function to fetch user views from the API
      const fetchUserViews = (jf: Api) =>
        Effect.tryPromise({
          try: async () => {
            const { getUserViewsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/user-views-api"
            );
            return await getUserViewsApi(jf).getUserViews();
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const getLibraries = () =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();

          // Step 1: Fetch user views from API
          const response = yield* fetchUserViews(jf).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          // Step 2: Validate the HTTP response
          // const validResponse = yield* validateResponse(response);

          // Step 3: Filter libraries to only include supported collection types
          const filteredLibraries = yield* filterSupportedLibraries(
            response.data?.Items
          );

          // Step 4: Add image URLs to each library
          const librariesWithImages = yield* getImages(jf)(filteredLibraries);

          return librariesWithImages;
        });

      /*
       *
       *
       *  Items Helpers
       *
       *
       */
      const fetchItems = (jf: Api, params: ItemsApiGetItemsRequest) =>
        Effect.tryPromise({
          try: async () => {
            const { getItemsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/items-api"
            );
            return await getItemsApi(jf).getItems(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchResumeItems = (
        jf: Api,
        params: ItemsApiGetResumeItemsRequest
      ) =>
        Effect.tryPromise({
          try: async () => {
            const { getItemsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/items-api"
            );
            return await getItemsApi(jf).getResumeItems(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchNextupItems = (jf: Api, params: TvShowsApiGetNextUpRequest) =>
        Effect.tryPromise({
          try: async () => {
            const { getTvShowsApi } = await import(
              "@jellyfin/sdk/lib/utils/api/tv-shows-api"
            );
            return await getTvShowsApi(jf).getNextUp(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchLatestItems = (
        jf: Api,
        params: UserLibraryApiGetLatestMediaRequest
      ) =>
        Effect.tryPromise({
          try: async () => {
            const { getUserLibraryApi } = await import(
              "@jellyfin/sdk/lib/utils/api/user-library-api"
            );
            return await getUserLibraryApi(jf).getLatestMedia(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });

      const fetchPlaybackState = (
        jf: Api,
        params: MediaInfoApiGetPlaybackInfoRequest
      ) =>
        Effect.tryPromise({
          try: async () => {
            const { getMediaInfoApi } = await import(
              "@jellyfin/sdk/lib/utils/api/media-info-api"
            );
            return await getMediaInfoApi(jf).getPlaybackInfo(params);
          },
          catch: (e) => new HttpError({ status: 0, message: String(e) }),
        });
      /*
       *
       *
       *  Items Methods
       *
       *
       */
      const getItem = (id: string, params?: ItemsApiGetItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchItems(jf, {
            userId: user.Id,
            ids: [id],
            enableImages: true,
            enableUserData: true,
            ...params,
            fields: [
              "ParentId",
              "ChildCount",
              "Path",
              "MediaStreams",
              "Chapters",
              "MediaSources",
              ...(params?.fields ? [...params.fields] : []),
            ],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const item = res.data.Items[0];

          return yield* getImages(jf)(item);
        });

      const getItems = (params?: ItemsApiGetItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchItems(jf, {
            userId: user.Id,
            ...params,
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data.Items;

          return yield* getImages(jf)(items);
        });

      const getResumeItems = (params?: ItemsApiGetResumeItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchResumeItems(jf, {
            userId: user.Id,
            enableUserData: true,
            limit: 6,
            ...params,
            fields: ["ParentId", "MediaSources", "MediaStreams"].concat(
              params?.fields ?? []
            ) as ItemFields[],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data.Items;

          return yield* getImages(jf)(items);
        });

      const getNextupItems = (params?: ItemsApiGetResumeItemsRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchNextupItems(jf, {
            userId: user.Id,
            enableUserData: true,
            limit: 6,
            ...params,
            fields: ["ParentId", "MediaSources", "MediaStreams"].concat(
              params?.fields ?? []
            ) as ItemFields[],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (
            (res.data.Items && isEmptyArray(res.data.Items)) ||
            res.data.Items === undefined
          ) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data.Items;

          return yield* getImages(jf)(items);
        });

      const getLatestMedia = (params?: UserLibraryApiGetLatestMediaRequest) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchLatestItems(jf, {
            userId: user.Id,
            enableUserData: true,
            limit: 6,
            ...params,
            fields: ["ParentId"].concat(params?.fields ?? []) as ItemFields[],
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if ((res.data && isEmptyArray(res.data)) || res.data === undefined) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }

          const items = res.data;

          return yield* getImages(jf)(items);
        });

      const getNextEpisode = (item: BaseItemDto) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          if (!item.IndexNumber) {
            return yield* new NoEpisodeFound();
          }

          // Current Episode Details
          const seasonId = item.ParentId ?? undefined;
          const currentIndex = item.IndexNumber;

          // Fetch all episodes in this season; we cannot rely on
          // `startIndex` to filter by IndexNumber — it is a pagination
          // offset, so e.g. on episode 1 (currentIndex+1=2) the API
          // returns the third episode in the result set, skipping the
          // actual next one. Likewise, we cannot trust the returned
          // sort order, so we pick the candidate with the smallest
          // IndexNumber strictly greater than the current episode.
          const res = yield* getItems({
            userId: user.Id,
            parentId: seasonId,
            fields: ["ParentId", "MediaStreams", "ParentId"],
            enableUserData: true,
            includeItemTypes: ["Episode"],
            sortBy: ["IndexNumber"],
            sortOrder: ["Ascending"],
            enableImages: true,
          });

          const next = res.reduce<(typeof res)[number] | undefined>(
            (best, candidate) => {
              if (typeof candidate.IndexNumber !== "number") {
                return best;
              }
              if (candidate.IndexNumber <= currentIndex) {
                return best;
              }
              if (
                !best ||
                typeof best.IndexNumber !== "number" ||
                candidate.IndexNumber < best.IndexNumber
              ) {
                return candidate;
              }
              return best;
            },
            undefined
          );

          if (!next) {
            return yield* new NoEpisodeFound();
          }

          return yield* getImages(jf)(next);
        });

      const getPlaybackState = (
        id: string,
        params?: MediaInfoApiGetPlaybackInfoRequest
      ) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();

          const res = yield* fetchPlaybackState(jf, {
            userId: user.Id,
            itemId: id,
            ...params,
          }).pipe(
            Effect.flatMap((data) =>
              data.status !== 200
                ? Effect.fail(
                    new HttpError({
                      status: data.status,
                      message: data.statusText,
                    })
                  )
                : Effect.succeed(data)
            )
          );

          if (!res.data) {
            return yield* Effect.fail(
              new HttpError({
                status: 404,
                message: "no item found",
              })
            );
          }
          return res.data;
        });
      /*
       *
       *
       *
       *
       *
       * Mutations
       *
       *
       *
       *
       *
       */
      const markItemPlayed = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getPlaystateApi } = await import(
                "@jellyfin/sdk/lib/utils/api/playstate-api"
              );
              await getPlaystateApi(jf).markPlayedItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkPlayedItem",
                message: (e as Error).message,
              }),
          });
        });

      const markItemUnPlayed = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getPlaystateApi } = await import(
                "@jellyfin/sdk/lib/utils/api/playstate-api"
              );
              await getPlaystateApi(jf).markUnplayedItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkUnPlayedItem",
                message: (e as Error).message,
              }),
          });
        });

      const markItemFavorite = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getUserLibraryApi } = await import(
                "@jellyfin/sdk/lib/utils/api/user-library-api"
              );
              await getUserLibraryApi(jf).markFavoriteItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkItemFavorite",
                message: (e as Error).message,
              }),
          });
        });

      const markItemUnFavorite = (id: string) =>
        Effect.gen(function* () {
          const jf = yield* auth.getApi();
          const user = yield* auth.getUser();
          yield* Effect.tryPromise({
            try: async (signal) => {
              const { getUserLibraryApi } = await import(
                "@jellyfin/sdk/lib/utils/api/user-library-api"
              );
              await getUserLibraryApi(jf).unmarkFavoriteItem(
                {
                  userId: user.Id,
                  itemId: id,
                },
                { signal }
              );
            },
            catch: (e) =>
              new MutationError({
                mutation: "MarkItemUnFavorite",
                message: (e as Error).message,
              }),
          });
        });

      return {
        getLibraries,
        getItem,
        getItems,
        getResumeItems,
        getNextupItems,
        getLatestMedia,
        getNextEpisode,
        getPlaybackState,

        /*
         *
         * Mutations
         *
         */

        markItemPlayed,
        markItemUnPlayed,
        markItemFavorite,
        markItemUnFavorite,
      };
    }),
  }
) {}

export const JellyfinServiceLayer = JellyfinService.Default;

import type {
  BaseItemDto,
  ItemsApiGetItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { SolidQueryOptions } from "@tanstack/solid-query";
import { Effect, pipe } from "effect";
import type { Accessor } from "solid-js";
import { HttpError } from "~/effect/error";
import {
  createEffectMutation,
  createEffectQuery,
  createQueryDataHelpers,
  createQueryKey,
  type ExtractQueryData,
} from "~/effect/tanstack/query";
import { safeAssign } from "~/lib/utils";
import { JellyfinService, type WithImage } from "./service";

const LIBRARIES_TIMEOUT = "10 seconds";

class Jellyfin {
  librariesQueryKey = createQueryKey("getLibraries");
  librariesQueryDataHelpers = createQueryDataHelpers(this.librariesQueryKey);
  getLibraries = () =>
    createEffectQuery(() => ({
      queryKey: this.librariesQueryKey(),
      queryFn: () =>
        JellyfinService.pipe(
          Effect.flatMap((jf) => jf.getLibraries()),
          Effect.timeoutFail({
            duration: LIBRARIES_TIMEOUT,
            onTimeout: () =>
              new HttpError({
                status: 408,
                message:
                  "Loading libraries from Jellyfin timed out. Please try again.",
              }),
          })
        ),
    }));

